-- Must return six rows; absence fails the lifecycle gate.
SELECT TABLE_NAME FROM USER_TABLES WHERE TABLE_NAME IN ('CPF_EDU_OPERATION','CPF_EDU_OPERATION_TARGET','CPF_EDU_OPERATION_AUDIT','CPF_EDU_OUTBOX','CPF_EDU_LEASE','CPF_EDU_BUSINESS_RECORD') ORDER BY TABLE_NAME;
SELECT INDEX_NAME FROM USER_INDEXES WHERE INDEX_NAME IN ('IX_CPF_EDU_OPERATION_STATE','IX_CPF_EDU_OUTBOX_READY','IX_CPF_EDU_BUSINESS_STATE','IX_CPF_EDU_BUSINESS_FENCE') ORDER BY INDEX_NAME;

-- REF-owned independent counterparty simulator persistence
SELECT COUNT(*) AS CPF_EDU_COUNTERPARTY_REQUEST_COUNT FROM CPF_EDU_COUNTERPARTY_REQUEST;
